public class METCrossDockSalesFinalizationFacade
{
    WMSPickingRouteID wmsPickingRouteId = '';
    boolean skipTMSProcess = false;
    RecordSortedList wmsRouteList = new RecordSortedList(tableNum(WMSPickingRoute));
}

Method.Source:
/// <summary>
/// Post intercompany picking list
/// </summary>
private boolean postIntercompanyPickingList(SalesTable _salesTable)
{
    PurchTable      purchTable_Reference    = _salesTable.referencePurchTable();
    boolean         ret;

    if ((!purchTable_Reference.RecId && !purchTable_Reference.InterCompanySalesId) || !TradeInterCompany::checkDataAreaAccess(purchTable_Reference.InterCompanyCompanyId))
    {
        ret = true;
    }
    else if (purchTable_Reference.RecId)
    {
        changeCompany(purchTable_Reference.InterCompanyCompanyId)
        {
            ret = this.postPickingList(purchTable_Reference.interCompanySalesTable());
        }
    }

    return ret;
}

/// <summary>
/// Initialize the instance of <c>METCrossDockSalesFinalizationFacade</c>
/// </summary>
public void new(boolean _skipTMSProcess)
{
    skipTMSProcess = _skipTMSProcess;
}

/// <summary>
/// Constructs a new object instance of <c>METCrossDockSalesFinalizationFacade</c>
/// </summary>
/// <returns>Returns a new instance of <c>METCrossDockSalesFinalizationFacade</c></returns>
public static METCrossDockSalesFinalizationFacade construct(boolean _skipTMSProcess = false)
{
    return new METCrossDockSalesFinalizationFacade(_skipTMSProcess);
}

/// <summary>
/// Check if wave details need to be created in the system for the sales order
/// </summary>
/// <param name = "_salesTable">Table buffer of of <t>SalesTable</t></param>
/// <param name = "_inventLocation">Table buffer of type <t>InventLocation</t></param>
/// <returns>true if wave is required, otherwise false</returns>
private boolean isWaveRequired(SalesTable _salesTable, InventLocation _inventLocation)
{
    boolean ret = false;

    METWaveLine metWaveLine;

    select firstonly RecId from metWaveLine
        where metWaveLine.DocumentNumber == _salesTable.SalesId
        && metWaveLine.Type == METType::SalesOrder;

    if (_salesTable.salesid && DateTimeUtil::minValue() != _salesTable.METOrderExtractDateTime
            && _inventLocation.METWaveRequired == NoYes::Yes && _inventLocation.METCSDWarehouse == NoYes::Yes
            && _inventLocation.METPickDirector == NoYes::Yes && !metWaveLine.RecId)
    {
        ret = true;
    }

    return ret;
}

private boolean validate(SalesTable _salesTable, InventTransferId _transferId)
{
    METInventTransferTableExt metTransTable;
    InventTransferTable inventTransferTable;

    select firstonly inventTransferTable
        exists join metTransTable
        where inventTransferTable.RecId == metTransTable.InventTransferTable
        && metTransTable.SalesId == _salesTable.SalesId
        && inventTransferTable.TransferStatus != InventTransferStatus::Received
        && inventTransferTable.TransferId != _transferId;

    return inventTransferTable.RecId == 0;
}

/// <summary>
/// Validate and process sales order document posting and shipment process.
/// </summary>
/// <param name = "_transferId">Transfer order reference</param>
/// <param name = "_skipDeliveryReminder">Flag to skip updating delivery reminder</param>
public boolean process(InventTransferId _transferId, boolean _skipDeliveryReminder = false)
{
    InventParameters inventParameters = InventParameters::find();
    InventTransferTable inventTransferTable;
    METInventTransferTableExt metTransferTable;
    SalesTable salesTable;
    InventLocation inventLocation;
    boolean ret = true;

    select firstonly salesTable
        where salesTable.METOrderExtractStatus == METOrderExtractStatus::Extracted
              && salesTable.SalesStatus == SalesStatus::Backorder
        join firstonly inventLocation
            where inventLocation.InventLocationId == salesTable.InventLocationId
        join TransferType from metTransferTable
            where metTransferTable.SalesId == salesTable.SalesId
                && metTransferTable.OrderExtractStatus == METOrderExtractStatus::Extracted
                && metTransferTable.TransferType != METCrossDockTransferType::None
        exists join inventTransferTable
            where inventTransferTable.RecId == metTransferTable.InventTransferTable
                && inventTransferTable.TransferId == _transferId;

    if (this.isWaveRequired(salesTable, inventLocation))
    {
        salesTable.createWaveFromSalesTable();
    }

    if (salesTable && metTransferTable.TransferType != METCrossDockTransferType::None)
    {
        // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
        // In TO finalisation, before the SO picking list, the SO reservation qty needs to be initalised from the TO received qty
        this.reservePhysicalQty(salesTable, _transferId, _skipDeliveryReminder);

        //Post picking list
        ret = this.postPickingList(salesTable, _transferId);

        //Post intercompany picking list. Sourcing all lines from a single company
        ret = this.postIntercompanyPickingList(salesTable);

    }

    return ret;
}

private void postPickingListRegistration(WMSPickingRouteID _pickingRouteID)
{
    List list = new List(Types::String);

    list.addEnd(_pickingRouteID);

    WMSPickingRoute::finishMulti(list.pack());   // Note - this is not in a single tts, so some routes might be posted and others fail
}

private WMSPickingRouteID getTransferPickListReference(WMSPickingRoute _wmsPickingRoute)
{
    SalesLine salesLine;
    WMSOrderTrans orderTrans;

    select firstonly orderTrans
        where orderTrans.shipmentId == _wmsPickingRoute.shipmentId
        && orderTrans.routeId == _wmsPickingRoute.pickingRouteID
        join salesLine
        where salesLine.InventTransId == orderTrans.inventTransId
        && salesLine.SalesId == orderTrans.inventTransRefId;

    WMSPickingRoute transferPickingRoute;

    if(salesLine)
    {
        METInventTransferLine metTransLine;
        InventTransferLine transferLine;

        select firstonly metTransLine
            where metTransLine.SalesLineTransId == salesLine.InventTransId
            join transferLine 
            where transferLine.RecId == metTransLine.InventTransferLine;

        select firstonly transferPickingRoute
            where transferPickingRoute.transRefId == transferLine.TransferId
            && transferPickingRoute.transType == InventTransType::TransferOrderShip;

    }

    return transferPickingRoute.pickingRouteID;
}

/// <summary>
/// Post picking list
/// </summary>
/// <param name = "_salesTable">SalesTable buffer.</param>
/// <param name = "_transferId">Optional; Transfer Id.</param>
/// <returns>Boolean tag</returns>
private boolean postPickingList(SalesTable _salesTable, InventTransferId _transferId = '')
{
    boolean ret;

    // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
    // Refactoring to use the existing code from METSalesPickingListGenerationTaskService instead of having a separate method for xDock
    METSalesPickingListGenerationTaskService_CrossDock salesPickingListGenerationTaskService_CrossDock = new METSalesPickingListGenerationTaskService_CrossDock();
    salesPickingListGenerationTaskService_CrossDock.setSkipTMSProcess(skipTMSProcess);
    salesPickingListGenerationTaskService_CrossDock.parmTransferId(_transferId);
    salesPickingListGenerationTaskService_CrossDock.postPickingList(_salesTable);
    WMSPickingRoute wmsPickingRoute = salesPickingListGenerationTaskService_CrossDock.getWMSPickingRoute();
    wmsRouteList.ins(wmsPickingRoute);

    // Moved the picking list registration after postPickingList
    if (wmsPickingRoute)
    {
        //If the default wmsLocation is not set at the Sales order level, update the same before pick list registration.
        this.updateWMSPickLocation(wmsPickingRoute);
        this.postPickingListRegistration(wmsPickingRoute.pickingRouteID);

        wmsPickingRoute.reread();

        if (wmsPickingRoute.expeditionStatus == WMSExpeditionStatus::Complete)
        {
            ret = true;
        }
    }

    return ret;
}

/// <summary>
/// Get the list of WMS picking routes to be sent to TMS engine
/// </summary>
/// <returns>Record sorted list with <t>WMSPickingRoute</t> table buffer</returns>
public RecordSortedList getWMSPickingRoute()
{
    return wmsRouteList;
}

private void updateWMSPickLocation(WMSPickingRoute _wmsPickingRoute)
{
    WMSOrderTrans orderTrans;
    InventDim inventDim;

    while select forupdate orderTrans
        where orderTrans.routeId == _wmsPickingRoute.pickingRouteID
        join inventDim
        where inventDim.inventDimId == orderTrans.inventDimId
        && inventDim.wMSLocationId == ''
    {
        InventDim inventDimLoc = inventDim;
        ttsbegin;
        inventDimLoc.wMSLocationId = InventLocation::find(inventDim.InventLocationId).WMSlocationIdDefaultIssue;
        orderTrans.inventDimId = inventDim::findOrCreate(inventDimLoc).inventDimId;
        orderTrans.update();
        ttscommit;
    }
}

/// <summary>
/// Created for the CB274 - Intercompany Transfers.
/// Exclude the SO  line for extraction if it's a food item.
/// Create a Purchase order for the food item line.
/// </summary>
/// <param name = "_shipmentId">Shipment Id reference</param>
/// <returns>SysQueryRun</returns>
private SysQueryRun calcQuery(SalesTable _salesTable)
{
    Query                   qry = new Query(QueryStr(SalesUpdate));
    SalesLine               salesLine;
    METSalesLine            metSalesLine;
    QueryBuildRange         qbrSalesLine;
    QueryBuildDataSource    qbdsSalesLine;
    METSalesTable           metSalesTable = METSalesTable::findBySalesTable(_salesTable.RecId);

    qbdsSalesLine = qry.dataSourceTable(tableNum(SalesLine));

    while select salesLine
        where salesLine.SalesId == _salesTable.SalesId
        && salesLine.SalesStatus != SalesStatus::Canceled
            join metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
    {
        InventDim inventDim = salesLine.inventDim();

        if(metSalesLine.OrderExtractStatus == METOrderExtractStatus::Extracted)
        {
            if(!(metSalesTable.InternalCrossDockOrder || inventDim.inventLocation().METCSDWarehouse))
            {
                continue;
            }
        }

        if (InventTable::metGetOSCCode(salesLine.ItemId, inventDim) == METConstants::GroceryOscCode &&
            _salesTable.METIntercompanyTransferFulfillment == NoYes::Yes
            && _salesTable.InterCompanyOrigin != InterCompanyOrigin::Derived)
        {
            METSalesOrderProcessHelper::createPOForIntercompanyFulfillment(_salesTable, salesLine);
        }
        else
        {
            qbrSalesLine = qbdsSalesLine.addRange(fieldnum(SalesLine, RecId));

            qbrSalesLine.value(SysQuery::value(salesLine.RecId));
        }
    }

    return new sysQueryRun(qry);
}

/// <summary>
/// Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
/// Method to reserve SO physical qty straight after TO receipt
/// </summary>
/// <param name = "_salesTable">Sales order to reserve physical qty after TO receipt</param>
/// <param name = "_transferId">TO received</param>
/// <param name = "_skipDeliveryReminder">Flag to skip updating delivery reminder</param>
private void reservePhysicalQty(SalesTable _salesTable, InventTransferId _transferId, boolean _skipDeliveryReminder = false)
{
    InventTransferLine      inventTransferLine;
    METInventTransferLine   metInventTransferLine;
    SalesLine               salesLine;

    // For each TO line originating from SO line (xDock)
    while select QtyReceived, ItemId, QtyTransfer, UnitId from inventTransferLine
           where inventTransferLine.TransferId == _transferId
            join metInventTransferLine
           where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
            join InventTransId, QtyOrdered, RemainSalesPhysical, RemainInventPhysical, SalesUnit from salesLine
           where salesLine.InventTransId == metInventTransferLine.SalesLineTransId
           // Bug 367203: CSD Perishables partial pick TO not being received
           // For CSD orders, SO lines are already canceled from METPickingListRegistrationPostingJob when calling orderTrans.metShortPickDeliveryReminderUpd()
           // Adding new condition to make sure we are not calling updateDeliveryReminder again if the line has already been cancelled
           && salesLine.SalesStatus != SalesStatus::Canceled
    {
        METInventTransReserveService reserveService;
        boolean                      partialReserve;

        reserveService = METInventTransReserveService::construct(salesLine.InventTransId, salesLine.QtyOrdered);
        reserveService.parmPickPartialReservedLine(true);

        // reserve the TO receipt qty against the corresponding SO line
        reserveService.reserve(inventTransferLine.QtyReceived);

        if (_skipDeliveryReminder == false)
        {
            // Update the delivery remainder on the SO line
            this.updateDeliveryReminder(inventTransferLine, salesLine, _salesTable);
        }
    }
}

/// <summary>
/// If the transfer order line is not fully reserved, then update the delivery remainder on the sales line.
/// </summary>
/// <param name = "_inventTransferLine"><t>InventTransferLine</t> table buffer</param>
/// <param name = "_salesLine"><t>SalesLine</t> table buffer</param>
private void updateDeliveryReminder(InventTransferLine _inventTransferLine, SalesLine _salesLine, SalesTable _salesTable)
{
    //CB238 236447 Part 3 update delivery remainder
    SalesQty qtyShortageSalesUnit;
    InventTable inventTable;
    boolean isFullyReserved;

    select firstonly Product from inventTable
        where inventTable.ItemId == _inventTransferLine.ItemId;

    // Determine if the SO line is fully reserved
    isFullyReserved = (_inventTransferLine.QtyTransfer <= _inventTransferLine.QtyReceived);

    if (!isFullyReserved)
    {
        // Bug 297848: CB679 SO line cancelled & Back order not created
        // If the SO has “Allow backorder” = Yes and TO line has “Transfer quantity” > “Received quantity”
        if (_salesTable.METAllowBackOrders)
        {
            // update the extraction status of the linked line to Open 
            METSalesLine metSalesLineUpd = METSalesLine::find(_salesLine.RecId, true);
            metSalesLineUpd.OrderExtractStatus = METOrderExtractStatus::Open;
            metSalesLineUpd.update();
        }
        else
        {
            SalesQty qtyShortage = _inventTransferLine.QtyTransfer - _inventTransferLine.QtyReceived;

            // Get the unit of measure for the sales unit to update the delivery remainder
            qtyShortageSalesUnit = UnitOfMeasureConverter::convert(qtyShortage,
               UnitOfMeasure::unitOfMeasureIdBySymbol(_inventTransferLine.UnitId),
               UnitOfMeasure::unitOfMeasureIdBySymbol(_salesLine.SalesUnit),
               NoYes::Yes,
               inventTable.Product,
               NoYes::Yes);

            // Update the SO line's delivery remainder fields
            SalesLine salesLineUpd = SalesLine::findInventTransId(_salesLine.InventTransId, true);

            if (salesLineUpd)
            {
                SalesUpdateRemain salesUpdateRemain = SalesUpdateRemain::construct();
                boolean updated = salesUpdateRemain.updateDeliverRemainder(
                salesLineUpd,
                salesLineUpd.RemainSalesPhysical - qtyShortageSalesUnit,
                salesLineUpd.RemainInventPhysical - qtyShortage,
                salesLineUpd.orig().PdsCWRemainInventPhysical - (_inventTransferLine.PdsCWQtyTransfer - _inventTransferLine.PdsCWQtyReceived));
            }
        }
    }
}
